      "path": "plugins/dsh-orchestrator2/presets/orchestrator2/dispatch.mjs",
      "content": "/**\n * Orchestrator2 dispatch half-step: the atomic pair around a subagent dispatch.\n *\n * Registers four model-facing tools that the scheduler must call as\n * `dispatch_begin → subagent_* → dispatch_end` (persona 【阶段二】三段式),\n * plus `dispatch_status`（恢复轮视图）与 `dispatch_migrate`（旧台账迁移）：\n *\n *   dispatch_begin(taskDir, 环节, 角色)\n *     原子完成：读 状态.md 固定块（fail-closed）→ 读 预算台账.md 固定块对照\n *     任务包预算块三项硬上限（**达上限即派工前拒绝**）→ 台账 schema v2 惰性升级\n *     （v1 → v2：补身份行+新列，写回前备份 v1 原文）→ 写 <taskDir>/.lock\n *     （内容含 环节/角色/时间戳/runId）→ 台账**预登记**一行（结论列 = 已派工，\n *     runId 列 = 完整 runId）→ 返回 runId。\n *\n *   dispatch_end(taskDir, runId, 结论, 结果态?)\n *     原子完成：读 .lock 核对 runId（防跨轮错配）→ 阶段前移合法性校验\n *     （结果态 DONE/DONE_WITH_CONCERNS 要求阶段已前移；DONE_WITH_CONCERNS 另要求\n *     执行自测文档含「concerns」固定小节，否则按证据缺失拒绝结算保留锁；\n *     NEEDS_CONTEXT/BLOCKED/FAILED/INTERRUPTED 四态允许不前移——仍结算本行、\n *     计次、释放锁，消息明示下一步）→ 台账按**完整 runId 精确匹配**回填该行\n *     （结论列 = 中文摘要照旧 +〔结果态枚举〕+ 结算后阶段/候选commit/token）\n *     → 删锁。无「第一条已派工行」回退路径：找不到 runId 对应的已派工行 =\n *     拒绝回填并保留锁。\n *\n *   dispatch_status(taskDir)（恢复轮用）\n *     台账明细 + 悬空识别 + **四方一致检查**（账本身份行 vs 状态.md 头 vs\n *     候选 commit vs 证据文件存在性）+ **续跑建议**（已有「通过结论行」\n *     = 结论列状态词为 DONE 或 DONE_WITH_CONCERNS 的结算行——的环节不得重派，\n *     指向第一个无结论环节）。\n *\n *   dispatch_migrate(taskDir)（D5 旧台账迁移）\n *     v1 → v2 一次性转换：补身份行（taskId/repoRelativeTaskPath/flowType 从任务\n *     目录与状态头推断）→ 明细列补齐（runId 等缺列填「—」）→ 不可解析行原样\n *     保留并标注；写回前备份原文到 预算台账-v1备份-YYYYMMDD.md；已是 v2 则空操作。\n *\n * 恢复轮语义：台账里存在「已派工」行且 <taskDir>/.lock 仍在 → 该环节为**悬空**\n * （派工已点火、回填未完成），凭 `dispatch_status` 即可一眼识别，不必猜。\n *\n * 形态说明（T0 只读探查结论 = 形态 A）：本模块与 `phase-gate.mjs` / `budget.mjs`\n * 同为**预设内本地插件**——`agent.cordis.yml` 里以相对路径 `./dispatch.mjs` 声明，\n * 库加载器的 `tree.import()` 对以 `.` 开头的 name 走 `new URL(name, ctx.baseUrl)`\n * 解析（baseUrl = 预设目录），命中的正是「预设内工具模块」这一形态；零宿主改动、\n * 零新增权限面（与既有两个工具同层）。故**不需要**形态 B（CLI 子命令 + pwsh 调用）\n * 降级；降级预案仍保留在 persona 的 M2 段说明里，供宿主机制变更时切换。\n *\n * 台账 schema v2（TP-B · D1）：固定块增「账本身份」行\n *   账本身份：<taskId> | schemaVersion：2 | <repoRelativeTaskPath> | <flowType>\n * 明细表头增列 runId / attempt / 派工前阶段 / 结算后阶段 / candidateCommit /\n * evidencePath（身份不符 = 拒绝派工，防串档）。v1 台账在派工/迁移时惰性升级。\n * 本模块只做「预登记 / 回填 / 累计 +1 / 视图 / 迁移」五件事；固定块「当前累计」\n * 行与「最近更新」行同步重算（计划评审-v1.0 O-3）。\n */\n\nimport { existsSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs'\nimport { randomUUID } from 'node:crypto'\nimport { basename, isAbsolute, join, relative, sep } from 'node:path'\n\n/** Cordis plugin name used by loader diagnostics. */\nexport const name = 'orchestrator2-dispatch'\n\n/** Hard dependencies: the tool registry only (state lives in the project's markdown). */\nexport const inject = ['tools']\n\n/** 台账明细表头 v1（历史格式；用于识别并惰性升级）。 */\nconst LEDGER_HEADER_V1 = '| 时间 | 环节 | 模型 | 结论 | 累计C运行 | 累计B运行 | 累计工作轮 | token用量 |'\n/** 台账明细表头 v2（与 spec/templates/03-开发协同/_模板/预算台账.md 严格一致）。 */\nconst LEDGER_HEADER_V2 = '| 时间 | 环节 | 模型 | 结论 | runId | attempt | 派工前阶段 | 结算后阶段 | candidateCommit | evidencePath | 累计C运行 | 累计B运行 | 累计工作轮 | token用量 |'\n/** v2 结论列单元格内缀状态词的定界：中文摘要照旧 +〔STATE〕。 */\nconst STATE_TAG = /〔([A-Z_]+)〕/\n\n/** 结果态六枚举（TP-B · D3；06 §二-3 映射：中断↔INTERRUPTED、失败↔FAILED、通过↔DONE/DWC）。 */\nconst RESULT_STATES = ['DONE', 'DONE_WITH_CONCERNS', 'NEEDS_CONTEXT', 'BLOCKED', 'FAILED', 'INTERRUPTED']\n\n/** 台账固定块「上限」行里的三项上限。 */\nconst CAP_PATTERN = { c: /C运行≤(\\d+)/, b: /B运行≤(\\d+)/, r: /工作轮≤(\\d+)/ }\n/** 台账固定块「当前累计」行里的三项累计。 */\nconst USED_PATTERN = { c: /C运行=(\\d+)/, b: /B运行=(\\d+)/, r: /工作轮=(\\d+)/ }\n\n/** 角色 → 计次口径（B = 审核员 subagent_reviewer；C = 开发员 subagent_developer）。 */\nconst ROLE_TO_COUNTER = {\n  subagent_reviewer: 'b',\n  subagent_developer: 'c',\n}\n/** 角色枚举（宽松：允许「调度员」这类自办环节，但不计 B/C 次数）。 */\nconst ROLES = ['subagent_reviewer', 'subagent_developer', 'subagent_researcher', '调度员']\n\n/** 环节 → 证据文件名的映射（dispatch_status 四方一致检查用；修复包加「修复」前缀）。 */\nconst EVIDENCE_PATTERNS = [\n  [/计划审核|可行性复核/, /^计划评审-v.+\\.md$/],\n  [/代码审查/, /^代码审查-v.+\\.md$/],\n  [/修复/, /^修复(执行自测|代码审查)-.+\\.md$/],\n  [/执行与自测/, /^执行自测-.+\\.md$/],\n]\n\n/** Render any thrown value the way the goal-round-driver does. */\nfunction renderThrown(value) {\n  return value instanceof Error ? value.message : String(value)\n}\n\n/** Whether one path exists and is a regular file. */\nfunction isFile(path) {\n  try {\n    return statSync(path).isFile()\n  } catch {\n    return false\n  }\n}\n\n/** 解析固定块（与 phase-gate.parseFixedBlock 同规则的最小实现）。 */\nfunction parseFixedBlock(text) {\n  const fields = new Map()\n  const lines = String(text).split(/\\r\\n|\\r|\\n/)\n  let i = 0\n  while (i < lines.length && lines[i].trim() === '') i++\n  while (i < lines.length && lines[i].trim() === '---') i++\n  for (; i < lines.length; i++) {\n    const line = lines[i].trimEnd()\n    if (line.length === 0 || line.trim() === '---') break\n    const sep = line.indexOf('：')\n    if (sep <= 0) break\n    const key = line.slice(0, sep).trim()\n    const value = line.slice(sep + 1).trim()\n    if (key.length === 0 || fields.has(key)) break\n    fields.set(key, value)\n  }\n  return fields\n}\n\n/** 读文件的固定块；不可读/不可解析返回 undefined。 */\nfunction fixedBlockOf(path) {\n  if (!isFile(path)) return undefined\n  try {\n    return parseFixedBlock(readFileSync(path, 'utf8'))\n  } catch {\n    return undefined\n  }\n}\n\n/** ISO 本地时间戳（台账「时间」列口径：YYYY-MM-DD HH:MM）。 */\nfunction nowStamp() {\n  const d = new Date()\n  const p = (n) => String(n).padStart(2, '0')\n  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`\n}\n\n/** 备份文件名日期口径：YYYYMMDD。 */\nfunction todayCompact() {\n  return nowStamp().slice(0, 10).replace(/-/g, '')\n}\n\n/** 解析任务目录入参 → 绝对路径。 */\nfunction resolveTaskDir(rootDir, input) {\n  const trimmed = typeof input === 'string' ? input.trim() : ''\n  if (trimmed.length === 0) return undefined\n  return isAbsolute(trimmed) ? trimmed : join(rootDir, trimmed)\n}\n\n/** 项目根：会话工作区 cwd，缺省进程 cwd（与 phase-gate 同口径）。 */\nfunction sessionRoot(agent) {\n  const cwd = agent?.session?.header?.cwd\n  if (typeof cwd === 'string' && cwd.length > 0) return cwd\n  return process.cwd()\n}\n\n/** 任务目录相对项目根的正斜杠路径（账本身份行口径）。 */\nfunction relTaskPath(rootDir, taskDir) {\n  return relative(rootDir, taskDir).split(sep).join('/')\n}\n\n/** 把一行明细拆成单元格数组（去首尾空串、去空白）。 */\nfunction splitCells(line) {\n  return line.split('|').slice(1, -1).map((c) => c.trim())\n}\n\n/** 该行是否为表格分隔行（|---|---|…）。 */\nfunction isSeparatorRow(line) {\n  return /^\\|[\\s|:-]+\\|$/.test(line.trim())\n}\n\n/**\n * 解析台账身份行：`账本身份：<taskId> | schemaVersion：2 | <repoRelativeTaskPath> | <flowType>`。\n * @returns {{taskId: string, schemaVersion: number, repoRelativeTaskPath: string, flowType: string} | undefined}\n */\nfunction parseIdentity(text) {\n  const m = text.match(/^账本身份：(.+)$/m)\n  if (m === null) return undefined\n  const parts = m[1].split(' | ').map((s) => s.trim())\n  if (parts.length < 4) return undefined\n  const sv = parts[1].match(/schemaVersion：(\\d+)/)\n  return {\n    taskId: parts[0],\n    schemaVersion: sv === null ? 1 : Number(sv[1]),\n    repoRelativeTaskPath: parts[2],\n    flowType: parts[3],\n  }\n}\n\n/** 依据任务目录与状态头构造身份行文本。 */\nfunction identityLineFor(rootDir, taskDir) {\n  const header = fixedBlockOf(join(taskDir, '状态.md'))\n  const flowType = header?.get('流程类型') ?? '—'\n  return `账本身份：${basename(taskDir)} | schemaVersion：2 | ${relTaskPath(rootDir, taskDir)} | ${flowType}`\n}\n\n/**\n * v1 → v2 台账文本升级（纯字符串处理，保留人读 Markdown —— 与 P2-2 口径一致）。\n * 标准 v1 表头：换 v2 表头 + 既有数据行补 6 个「—」列；不可解析行原样保留并标注。\n * 非标准表头（历史自定义台账）：保留明细原样，仅补身份行 + 迁移标注。\n * @returns {{text: string, upgraded: boolean, note: string}}\n */\nfunction upgradeLedgerText(text, rootDir, taskDir) {\n  if (parseIdentity(text)?.schemaVersion === 2) {\n    return { text, upgraded: false, note: '已是 schema v2' }\n  }\n  const lines = text.split(/\\r\\n|\\r|\\n/)\n  const idLine = identityLineFor(rootDir, taskDir)\n  // 身份行插在「任务包：」行之后（协同区台账第一行惯例），无该行则置顶。\n  const anchor = lines.findIndex((l) => l.startsWith('任务包：'))\n  lines.splice(anchor >= 0 ? anchor + 1 : 0, 0, idLine)\n\n  const headerIdx = lines.findIndex((l) => l.trim() === LEDGER_HEADER_V1)\n  let note = '标准 v1 → v2：明细列补齐（runId 等缺列填「—」）'\n  if (headerIdx >= 0) {\n    lines[headerIdx] = LEDGER_HEADER_V2\n    for (let i = headerIdx + 1; i < lines.length; i++) {\n      const l = lines[i]\n      if (!l.startsWith('|')) break\n      if (isSeparatorRow(l)) continue\n      const cells = splitCells(l)\n      // 标准 v1 数据行 = 8 列；新列插在「结论」之后（与 v2 表头列序一致）；其余按不可解析行处理。\n      if (cells.length === 8) {\n        lines[i] = `| ${[...cells.slice(0, 4), '—', '—', '—', '—', '—', '—', ...cells.slice(4)].join(' | ')} |`\n      } else {\n        lines.splice(i + 1, 0, '<!-- 迁移标注：上一行无法解析为 v1 明细行（列数不符），原样保留 -->')\n        i++\n      }\n    }\n  } else {\n    note = '非标准表头：仅补身份行，明细原样保留（见迁移标注）'\n    const tableIdx = lines.findIndex((l) => l.startsWith('|'))\n    if (tableIdx >= 0) lines.splice(tableIdx, 0, '<!-- 迁移标注：本台账明细表头非标准 v1/v2 格式，明细行原样保留，仅补身份行 -->')\n  }\n  return { text: lines.join('\\n'), upgraded: true, note }\n}\n\n/**\n * 读台账固定块（上限/当前累计）+ 身份行。\n * @returns {{ok: boolean, message: string, text?: string, caps?: object, useds?: object, identity?: object}}\n */\nfunction readLedger(path) {\n  if (!isFile(path)) {\n    return { ok: false, message: `缺少 ${path}：v2.x 任务包的预算台账是机器保险丝必填件（先建台账再派工）。` }\n  }\n  let text\n  try {\n    text = readFileSync(path, 'utf8')\n  } catch (error) {\n    return { ok: false, message: `预算台账不可读（${path}）：${renderThrown(error)}。` }\n  }\n  const cap = text.match(/^上限：(.*)$/m)\n  const used = text.match(/^当前累计：(.*)$/m)\n  if (cap === undefined || used === undefined) {\n    return { ok: false, message: `预算台账固定块不可解析（${path}）：需含「上限：…」与「当前累计：…」两行。` }\n  }\n  const pick = (pattern, source) => {\n    const m = source.match(pattern)\n    return m === null ? undefined : Number(m[1])\n  }\n  const caps = { c: pick(CAP_PATTERN.c, cap[1]), b: pick(CAP_PATTERN.b, cap[1]), r: pick(CAP_PATTERN.r, cap[1]) }\n  const useds = { c: pick(USED_PATTERN.c, used[1]), b: pick(USED_PATTERN.b, used[1]), r: pick(USED_PATTERN.r, used[1]) }\n  if ([caps.c, caps.b, caps.r, useds.c, useds.b, useds.r].some((n) => !Number.isFinite(n))) {\n    return { ok: false, message: `预算台账固定块三项上限/累计不全（${path}）：上限需含 C运行≤N / B运行≤N / 工作轮≤N，当前累计需含 C运行= / B运行= / 工作轮=。` }\n  }\n  return { ok: true, message: '', text, caps, useds, identity: parseIdentity(text) }\n}\n\n/** 把「当前累计」行重算写回，并同步「最近更新」（计划评审-v1.0 O-3：预登记/回填均刷新）。 */\nfunction writeUsageLine(text, useds, tokenText) {\n  let next = text.replace(/^当前累计：.*$/m, `当前累计：C运行=${useds.c} / B运行=${useds.b} / 工作轮=${useds.r} / token用量=${tokenText}`)\n  next = next.replace(/^最近更新：.*$/m, `最近更新：${nowStamp()}`)\n  return next\n}\n\n/** 解析明细区数据行（v1/v2 表头均可定位）；返回行号索引（相对原始行数组）。 */\nfunction ledgerRowsOf(text) {\n  const lines = text.split(/\\r\\n|\\r|\\n/)\n  const headerIdx = lines.findIndex((l) => l.trim() === LEDGER_HEADER_V2 || l.trim() === LEDGER_HEADER_V1)\n  if (headerIdx < 0) return { rows: [], v2: false, lines }\n  const v2 = lines[headerIdx].trim() === LEDGER_HEADER_V2\n  const rows = []\n  for (let i = headerIdx + 1; i < lines.length; i++) {\n    const l = lines[i]\n    if (!l.startsWith('|')) break\n    if (isSeparatorRow(l)) continue\n    rows.push({ idx: i, cells: splitCells(l) })\n  }\n  return { rows, v2, lines }\n}\n\n/** 台账明细行（schema v2 预登记行：结论列=已派工，runId 列=完整 runId）。 */\nfunction ledgerRowV2(stamp, 环节, 模型, 结论, runId, attempt, beforePhase, useds, tokenText) {\n  return `| ${stamp} | ${环节} | ${模型} | ${结论} | ${runId} | ${attempt} | ${beforePhase} | — | — | — | ${useds.c} | ${useds.b} | ${useds.r} | ${tokenText} |`\n}\n\n/** 把一行追加到明细表末尾（WAL 时序：插在最后一条表格行之后，保持账本 chronological）。 */\nfunction appendLedgerRow(text, row) {\n  const lines = text.split(/\\r\\n|\\r|\\n/)\n  const headerIdx = lines.findIndex((l) => l.trim() === LEDGER_HEADER_V2 || l.trim() === LEDGER_HEADER_V1)\n  if (headerIdx < 0) {\n    return { ok: false, message: `预算台账缺少明细表头（v1/v2 均未找到）：${LEDGER_HEADER_V2}` }\n  }\n  // 明细区 = 表头之后连续的表格行（含分隔行）；新行插在其后（时序追加，不在表顶）。\n  let insertAt = headerIdx + 1\n  while (insertAt < lines.length && lines[insertAt].startsWith('|')) insertAt++\n  lines.splice(insertAt, 0, row)\n  return { ok: true, message: '', text: lines.join('\\n') }\n}\n\n/** 环节在本台账已出现的次数 + 1（attempt 列口径：含预登记行）。 */\nfunction nextAttempt(rows, 环节) {\n  return rows.filter((r) => r.cells[1] === 环节).length + 1\n}\n\n/** 结论中文摘要 → 结果态推断（06 §二-3 映射；显式传「结果态」参数时不走此分支）。 */\nfunction inferResultState(结论) {\n  if (/中断/.test(结论)) return 'INTERRUPTED'\n  if (/失败/.test(结论)) return 'FAILED'\n  if (/concerns|疑点/i.test(结论)) return 'DONE_WITH_CONCERNS'\n  if (/通过/.test(结论)) return 'DONE'\n  return 'NEEDS_CONTEXT'\n}\n\n/** 执行自测文档是否含「concerns」固定小节（DONE_WITH_CONCERNS 的证据要求，D3）。 */\nfunction hasConcernsSection(taskDir) {\n  let files = []\n  try {\n    files = readdirSync(taskDir)\n  } catch {\n    return false\n  }\n  return files\n    .filter((f) => /^(修复)?执行自测-.+\\.md$/.test(f))\n    .some((f) => {\n      try {\n        return /(^|\\n)#+\\s*concerns\\b/im.test(readFileSync(join(taskDir, f), 'utf8'))\n      } catch {\n        return false\n      }\n    })\n}\n\n/** 工具参数 schema 片段。 */\nconst DISPATCH_BEGIN_PARAMETERS = {\n  type: 'object',\n  properties: {\n    taskDir: { type: 'string', description: '任务目录路径：相对项目根（如 03-开发协同/TP1-<名>）或绝对路径。' },\n    环节: { type: 'string', description: '本环节名（如 计划审核 / 执行与自测 / 代码审查 / 待修订）。' },\n    角色: { type: 'string', description: `派工角色：${ROLES.join(' / ')}。subagent_reviewer 计 B 运行，subagent_developer 计 C 运行。` },\n    模型: { type: 'string', description: '（可选）本环节实际使用的模型标识，写入台账「模型」列。' },\n  },\n  required: ['taskDir', '环节', '角色'],\n  additionalProperties: false,\n}\n\nconst DISPATCH_END_PARAMETERS = {\n  type: 'object',\n  properties: {\n    taskDir: { type: 'string', description: '任务目录路径（与 dispatch_begin 同一值）。' },\n    runId: { type: 'string', description: 'dispatch_begin 返回的 runId。' },\n    结论: { type: 'string', description: '本环节结论中文摘要（如 通过 / 驳回轮次1 / 异常返回），照旧写入台账结论列。' },\n    结果态: { type: 'string', description: `（可选）结果态六枚举：${RESULT_STATES.join(' / ')}。缺省按结论摘要推断（中断↔INTERRUPTED、失败↔FAILED、通过↔DONE/DONE_WITH_CONCERNS、其余 NEEDS_CONTEXT）。DONE/DONE_WITH_CONCERNS 要求阶段已前移；后四态不前移亦可结算（计次+释锁）。` },\n    token用量: { type: 'string', description: '（可选）本环节 token 用量（仅统计），缺省保留原值。' },\n  },\n  required: ['taskDir', 'runId', '结论'],\n  additionalProperties: false,\n}\n\nconst DISPATCH_OUTPUT_SCHEMA = {\n  type: 'object',\n  properties: {\n    ok: { type: 'boolean', description: '本原子操作是否成功。' },\n    message: { type: 'string', description: '给调度器（模型）的结果文本。' },\n    runId: { type: 'string', description: '派工标识（成功时）。' },\n  },\n  required: ['ok', 'message'],\n  additionalProperties: false,\n}\n\nfunction result(ok, message, runId) {\n  return { ok, message, ...(runId === undefined ? {} : { runId }) }\n}\n\n/** 锁文件路径与内容。 */\nfunction lockPath(taskDir) {\n  return join(taskDir, '.lock')\n}\n\n/** 不前移四态的下一步指引（dispatch_end 消息明示）。 */\nfunction nextStepHint(state) {\n  switch (state) {\n    case 'NEEDS_CONTEXT':\n      return '下一步：补充缺失上下文后下一轮重派本环节（不得同一模型原样重试）。'\n    case 'BLOCKED':\n      return '下一步：消除阻塞（依赖/环境/权限）后重派；持续阻塞请上报用户裁决。'\n    case 'FAILED':\n      return '下一步：先查根因再重派本环节；同环节重复失败 >3 轮出决策简报。'\n    case 'INTERRUPTED':\n      return '下一步：恢复轮按 dispatch_status 对账后续跑（中断条目照记）。'\n    default:\n      return ''\n  }\n}\n\n/**\n * 原子派工前置：预算上限校验 + 台账 schema v2 惰性升级 + 预登记。\n * @returns {{ok: boolean, message: string, runId?: string}}\n */\nexport function dispatchBegin(rootDir, taskDirInput, 环节, 角色, 模型 = '—') {\n  const taskDir = resolveTaskDir(rootDir, taskDirInput)\n  if (taskDir === undefined) return result(false, '参数 taskDir 不能为空。')\n  if (typeof 环节 !== 'string' || 环节.trim().length === 0) return result(false, '参数「环节」不能为空。')\n  if (typeof 角色 !== 'string' || 角色.trim().length === 0) return result(false, '参数「角色」不能为空。')\n\n  const statusPath = join(taskDir, '状态.md')\n  const header = fixedBlockOf(statusPath)\n  if (header === undefined) {\n    return result(false, `状态.md 固定块不可解析或文件缺失（${statusPath}）：fail-closed 拒绝派工（不写锁、不记台账）。`)\n  }\n  const phase = header.get('当前阶段')\n  if (phase === undefined) {\n    return result(false, `状态.md 固定块缺少「当前阶段」字段（${statusPath}）：fail-closed 拒绝派工。`)\n  }\n\n  const lock = lockPath(taskDir)\n  if (existsSync(lock)) {\n    return result(false, `已有在跑环节：${lock} 存在（内容：${readFileSync(lock, 'utf8').trim().split('\\n').join('；')}）。同一任务目录不得并发派工——请等该环节返回后 dispatch_end，或按失败与中断路径清残留锁（mtime > 30 分钟或对应子代理已不活跃）。`)\n  }\n\n  const ledgerPath = join(taskDir, '预算台账.md')\n  const ledger = readLedger(ledgerPath)\n  if (!ledger.ok) return result(false, ledger.message)\n\n  // D1 · 账本身份防串档：身份行存在且与任务目录不符 → 拒绝派工。\n  if (ledger.identity !== undefined) {\n    const rel = relTaskPath(rootDir, taskDir)\n    if (ledger.identity.taskId !== basename(taskDir) || ledger.identity.repoRelativeTaskPath !== rel) {\n      return result(false, `账本身份不符（防串档）：台账登记的是「${ledger.identity.taskId} | ${ledger.identity.repoRelativeTaskPath}」，本次派工任务目录是「${basename(taskDir)} | ${rel}」。拒绝派工——请人工核对 ${ledgerPath} 是否放错任务目录。`)\n    }\n  }\n\n  const counter = ROLE_TO_COUNTER[角色.trim()]\n  const useds = { ...ledger.useds }\n  const caps = ledger.caps\n  // 预算派工前拒绝：先算「本次派工后」的用量，超上限即拒绝（不写锁、不记账）\n  const planned = {\n    c: useds.c + (counter === 'c' ? 1 : 0),\n    b: useds.b + (counter === 'b' ? 1 : 0),\n    r: useds.r + 1,\n  }\n  const over = []\n  if (planned.c > caps.c) over.push(`C 运行 ${planned.c} > 上限 ${caps.c}`)\n  if (planned.b > caps.b) over.push(`B 运行 ${planned.b} > 上限 ${caps.b}`)\n  if (planned.r > caps.r) over.push(`工作轮 ${planned.r} > 上限 ${caps.r}`)\n  if (over.length > 0) {\n    return result(false, `预算触顶，派工前拒绝（${over.join('；')}）：本 goal 轮不派工。请按预算纪律停机 → 生成非技术化决策简报（决策记录.md 分歧类）→ 交用户裁决。`)\n  }\n\n  // D1 · schema v2 惰性升级（v1 → v2：补身份行+新列；写回前备份 v1 原文）\n  let ledgerText = ledger.text\n  let upgraded = false\n  if (ledger.identity?.schemaVersion !== 2) {\n    const up = upgradeLedgerText(ledger.text, rootDir, taskDir)\n    ledgerText = up.text\n    upgraded = up.upgraded\n  }\n  const rows = ledgerRowsOf(ledgerText).rows\n  const runId = `${basename(taskDir)}-${nowStamp().replace(/[-: ]/g, '')}-${randomUUID().slice(0, 8)}`\n  const stamp = nowStamp()\n  const withRow = appendLedgerRow(ledgerText, ledgerRowV2(stamp, 环节.trim(), (模型 || '—').trim(), '已派工', runId, nextAttempt(rows, 环节.trim()), phase.trim(), planned, '—'))\n  if (!withRow.ok) return result(false, `台账写入失败：${withRow.message}`)\n  const nextText = writeUsageLine(withRow.text, planned, '—')\n\n  // 写锁 → 落台账（预登记）。顺序：先锁后账；任何一步失败都回滚锁。\n  const lockBody = [\n    `任务目录：${basename(taskDir)}`,\n    `环节：${环节.trim()}`,\n    `角色：${角色.trim()}`,\n    `runId：${runId}`,\n    `派工时间：${stamp}`,\n    `派工前阶段：${phase}`,\n  ].join('\\n')\n  try {\n    writeFileSync(lock, lockBody + '\\n', 'utf8')\n  } catch (error) {\n    return result(false, `写锁失败（${lock}）：${renderThrown(error)}`)\n  }\n  if (upgraded) {\n    // D5 口径：升级写回前备份 v1 原文（同名备份已存在则保留最早一份）\n    const backupPath = join(taskDir, `预算台账-v1备份-${todayCompact()}.md`)\n    try {\n      if (!existsSync(backupPath)) writeFileSync(backupPath, ledger.text, 'utf8')\n    } catch (error) {\n      try { rmSync(lock, { force: true }) } catch { /* 回滚尽力而为 */ }\n      return result(false, `台账 v1 备份失败（${backupPath}）：${renderThrown(error)}；已回滚锁文件。`)\n    }\n  }\n  try {\n    writeFileSync(ledgerPath, nextText, 'utf8')\n  } catch (error) {\n    try { rmSync(lock, { force: true }) } catch { /* 回滚尽力而为 */ }\n    return result(false, `台账预登记失败（${ledgerPath}）：${renderThrown(error)}；已回滚锁文件。`)\n  }\n  return result(\n    true,\n    `已派工并预登记：runId=${runId}｜环节=${环节.trim()}｜角色=${角色.trim()}｜派工后累计 C=${planned.c}/${caps.c} B=${planned.b}/${caps.b} 工作轮=${planned.r}/${caps.r}${upgraded ? '｜台账已惰性升级 schema v2（v1 原文已备份）' : ''}。下一步用 run_in_background:false 调 ${角色.trim()}；子代理返回后调 dispatch_end(taskDir, runId, 结论, 结果态?)。`,\n    runId,\n  )\n}\n\n/**\n * 原子派工后置：runId 精确结算 + 阶段前移合法性校验（按结果态分支）+ 回填台账 + 删锁。\n * @returns {{ok: boolean, message: string}}\n */\nexport function dispatchEnd(rootDir, taskDirInput, runId, 结论, 结果态, token用量) {\n  const taskDir = resolveTaskDir(rootDir, taskDirInput)\n  if (taskDir === undefined) return result(false, '参数 taskDir 不能为空。')\n  if (typeof runId !== 'string' || runId.trim().length === 0) return result(false, '参数 runId 不能为空。')\n  if (typeof 结论 !== 'string' || 结论.trim().length === 0) return result(false, '参数「结论」不能为空。')\n\n  // D3 · 结果态：显式参数优先，缺省按中文摘要推断（06 §二-3 映射）。\n  const state = typeof 结果态 === 'string' && 结果态.trim().length > 0 ? 结果态.trim().toUpperCase() : inferResultState(结论)\n  if (!RESULT_STATES.includes(state)) {\n    return result(false, `结果态「${state}」不在六枚举内（${RESULT_STATES.join(' / ')}）：拒绝回填——请按六态返回格式重传。`)\n  }\n\n  const lock = lockPath(taskDir)\n  if (!isFile(lock)) {\n    return result(false, `无在跑环节：${lock} 不存在。runId 可能已回填（重复调用）或被中断清理——请用 dispatch_status 核对台账明细后再决定重派。`)\n  }\n  const lockText = readFileSync(lock, 'utf8')\n  const lockRunId = (lockText.match(/^runId：(.*)$/m) ?? [])[1]\n  if (typeof lockRunId !== 'string' || lockRunId.trim() !== runId.trim()) {\n    return result(false, `runId 不匹配：锁文件登记的是 ${String(lockRunId)}，本次传 ${runId.trim()}。拒绝回填（防跨轮错配）——请核对本次派工返回的 runId。`)\n  }\n  const beforePhase = ((lockText.match(/^派工前阶段：(.*)$/m) ?? [])[1] ?? '').trim()\n\n  const statusPath = join(taskDir, '状态.md')\n  const header = fixedBlockOf(statusPath)\n  if (header === undefined) {\n    return result(false, `状态.md 固定块不可解析或文件缺失（${statusPath}）：拒绝回填，保留锁（该环节视同未完成）。`)\n  }\n  const afterPhase = header.get('当前阶段')\n  if (typeof afterPhase !== 'string' || afterPhase.trim().length === 0) {\n    return result(false, `状态.md 固定块缺少「当前阶段」字段（${statusPath}）：拒绝回填，保留锁。`)\n  }\n\n  // D3 · 阶段前移校验按结果态分支：DONE/DWC 必须前移；后四态不前移是合法结算。\n  const advancing = state === 'DONE' || state === 'DONE_WITH_CONCERNS'\n  if (advancing && beforePhase.length > 0 && afterPhase.trim() === beforePhase) {\n    return result(false, `阶段未前移：派工前与当前「当前阶段」都是「${afterPhase.trim()}」。结果态 ${state} 要求子代理把阶段推进合法后继——请按失败路径重派或上报；确认要作废本次派工时手动删除 ${lock} 并在台账把该行结论改为「失败」。拒绝回填、保留锁。`)\n  }\n  if (state === 'DONE_WITH_CONCERNS' && !hasConcernsSection(taskDir)) {\n    return result(false, `结果态 DONE_WITH_CONCERNS 要求执行自测文档含「concerns」固定小节（02 §三 D3 / 06 §二-5）：${taskDir} 下未找到含 concerns 小节的 执行自测/修复执行自测 文档——按证据缺失拒绝结算、保留锁。请补写 concerns 小节后再结算（或改报 DONE/FAILED 并说明）。`)\n  }\n\n  const ledgerPath = join(taskDir, '预算台账.md')\n  const ledger = readLedger(ledgerPath)\n  if (!ledger.ok) return result(false, `${ledger.message}（拒绝回填，保留锁）`)\n\n  // D2 · runId 精确结算：只按完整 runId 匹配「已派工」行；找不到 = 拒绝回填保留锁；\n  // 行已有结论 = 重复结算拒绝。无「第一条已派工行」回退路径。\n  const { rows, lines } = ledgerRowsOf(ledger.text)\n  const hit = rows.filter((r) => r.cells.length >= 5 && r.cells[3] === '已派工' && r.cells[4] === runId.trim())\n  if (hit.length === 0) {\n    const settledSameRun = rows.some((r) => r.cells.length >= 5 && r.cells[4] === runId.trim() && r.cells[3] !== '已派工')\n    if (settledSameRun) {\n      return result(false, `重复结算拒绝：runId=${runId.trim()} 的台账行已有结论（非「已派工」）。该行不能再次回填——请用 dispatch_status 核对，禁止重复计次。保留锁。`)\n    }\n    return result(false, `台账里找不到 runId=${runId.trim()} 的「已派工」行：台账可能被外部改写或锁为残留。拒绝回填、保留锁——请人工核对 ${ledgerPath}。`)\n  }\n  const row = hit[0]\n  const candidateCommit = (header.get('候选commit') ?? '—').trim()\n  const cells = [...row.cells]\n  cells[3] = `${结论.trim().replace(/\\|/g, '/')}〔${state}〕`\n  if (cells.length >= 8) cells[7] = afterPhase.trim()\n  if (cells.length >= 9) cells[8] = candidateCommit === '无' ? '—' : candidateCommit\n  if (typeof token用量 === 'string' && token用量.trim().length > 0 && cells.length >= 14) cells[13] = token用量.trim()\n  lines[row.idx] = `| ${cells.join(' | ')} |`\n  const nextText = writeUsageLine(lines.join('\\n'), ledger.useds, '—')\n\n  try {\n    writeFileSync(ledgerPath, nextText, 'utf8')\n  } catch (error) {\n    return result(false, `台账回填失败（${ledgerPath}）：${renderThrown(error)}；保留锁。`)\n  }\n  try {\n    rmSync(lock, { force: true })\n  } catch (error) {\n    return result(false, `台账已回填，但删锁失败（${lock}）：${renderThrown(error)}。请手动删除该锁文件再继续。`)\n  }\n  const stateNote = advancing\n    ? `阶段 ${beforePhase || '（未知）'} → ${afterPhase.trim()}`\n    : `阶段未前移（${state} 为合法不前移态，已照常结算计次）`\n  return result(\n    true,\n    `已回填并解锁：runId=${runId.trim()}｜${stateNote}｜结论=${结论.trim()}〔${state}〕。${nextStepHint(state)}本环节完成，可按状态.md 继续推进。`,\n  )\n}\n\n/**\n * 派工台账状态视图（恢复轮用）：明细 + 悬空识别 + 四方一致检查 + 续跑建议。\n * 四方一致 = 账本身份行 vs 状态.md 头（当前阶段/候选commit）vs 证据文件存在性；\n * 「通过结论行」= 结论列状态词为 DONE 或 DONE_WITH_CONCERNS 的结算行——\n * 已有通过结论行的环节**不得重派**，续跑建议指向第一个无结论环节。\n * @returns {{ok: boolean, message: string}}\n */\nexport function dispatchStatus(rootDir, taskDirInput) {\n  const taskDir = resolveTaskDir(rootDir, taskDirInput)\n  if (taskDir === undefined) return result(false, '参数 taskDir 不能为空。')\n  const ledgerPath = join(taskDir, '预算台账.md')\n  const ledger = readLedger(ledgerPath)\n  if (!ledger.ok) return result(false, ledger.message)\n  const parsed = ledgerRowsOf(ledger.text)\n  const rows = parsed.rows\n  const pending = rows.filter((r) => r.cells[3] === '已派工')\n  const lock = lockPath(taskDir)\n  const lockExists = isFile(lock)\n\n  // ── D4 · 四方一致检查 ──────────────────────────────────────────────────────\n  const inconsistency = []\n  const rel = relTaskPath(rootDir, taskDir)\n  if (ledger.identity === undefined) {\n    inconsistency.push('账本身份行缺失（schema v1，可 dispatch_migrate 迁移）')\n  } else {\n    if (ledger.identity.taskId !== basename(taskDir) || ledger.identity.repoRelativeTaskPath !== rel) {\n      inconsistency.push(`账本身份与任务目录不符（台账=${ledger.identity.taskId} | ${ledger.identity.repoRelativeTaskPath}；实际=${basename(taskDir)} | ${rel}）`)\n    }\n    if (ledger.identity.schemaVersion === 2 && !parsed.v2) {\n      inconsistency.push('身份行登记 schemaVersion 2 但明细表头仍为 v1')\n    }\n  }\n  const header = fixedBlockOf(join(taskDir, '状态.md'))\n  const headerPhase = header?.get('当前阶段')\n  const headerCommit = (header?.get('候选commit') ?? '').trim()\n  const settledV2 = rows.filter((r) => r.cells.length >= 9 && r.cells[3] !== '已派工')\n  const lastSettled = settledV2[settledV2.length - 1]\n  if (lastSettled !== undefined) {\n    const settledPhase = lastSettled.cells[7]\n    if (settledPhase !== '—' && headerPhase !== undefined && settledPhase !== headerPhase.trim()) {\n      inconsistency.push(`状态头当前阶段（${headerPhase.trim()}）与最近结算行结算后阶段（${settledPhase}）不一致`)\n    }\n    const settledCommit = lastSettled.cells[8]\n    if (settledCommit !== '—' && headerCommit.length > 0 && headerCommit !== '无' && settledCommit !== headerCommit) {\n      inconsistency.push(`状态头候选commit（${headerCommit}）与最近结算行 candidateCommit（${settledCommit}）不一致`)\n    }\n    // 证据文件存在性（最近结算行的环节）\n    const h = lastSettled.cells[1]\n    const ev = EVIDENCE_PATTERNS.find(([re]) => re.test(h))\n    if (ev !== undefined) {\n      let files = []\n      try {\n        files = readdirSync(taskDir)\n      } catch { /* 目录不可读：按缺失处理 */ }\n      if (!files.some((f) => ev[1].test(f))) {\n        inconsistency.push(`最近结算行环节「${h}」的证据文件缺失（期望匹配 ${ev[1]}）`)\n      }\n    }\n  } else if (headerPhase === undefined) {\n    inconsistency.push('状态.md 固定块不可解析（无法对照当前阶段）')\n  }\n\n  // ── D4 · 续跑建议 ──────────────────────────────────────────────────────────\n  let resume = ''\n  if (rows.length > 0) {\n    const order = []\n    for (const r of rows) {\n      if (!order.includes(r.cells[1])) order.push(r.cells[1])\n    }\n    const passed = new Set(\n      settledV2\n        .filter((r) => { const m = r.cells[3].match(STATE_TAG); return m !== null && (m[1] === 'DONE' || m[1] === 'DONE_WITH_CONCERNS') })\n        .map((r) => r.cells[1]),\n    )\n    const next = order.find((h) => !passed.has(h))\n    const noResend = order.filter((h) => passed.has(h))\n    resume = next === undefined\n      ? `续跑建议：各环节均已有通过结论行${noResend.length > 0 ? `（${noResend.join('、')} 不得重派）` : ''}，按状态.md 当前阶段「${headerPhase ?? '（未知）'}」继续。`\n      : `续跑建议：下一环节 = ${next}${noResend.length > 0 ? `（${noResend.join('、')} 已有通过结论行，不得重派）` : ''}。`\n  }\n\n  const head = `派工台账：${rows.length} 行明细（schema ${parsed.v2 ? 'v2' : 'v1'}${ledger.identity ? `；身份=${ledger.identity.taskId}` : ''}；上限 C=${ledger.caps.c} B=${ledger.caps.b} 工作轮=${ledger.caps.r}；累计 C=${ledger.useds.c} B=${ledger.useds.b} 工作轮=${ledger.useds.r}）`\n  const checksLine = inconsistency.length > 0\n    ? `**四方一致检查：${inconsistency.length} 项不一致**（${inconsistency.join('；')}）——恢复轮先处置再推进。`\n    : '四方一致检查：一致（账本身份 / 状态头 / 候选commit / 证据文件）。'\n  if (pending.length > 0) {\n    return result(true, `${head}\\n${checksLine}\\n**悬空派工 ${pending.length} 行**（已点火、未回填）：\\n${pending.map((r) => '  ' + parsed.lines[r.idx]).join('\\n')}\\n锁文件 ${lock} ${lockExists ? '仍在（确认子代理已不活跃则可按失败路径处理）' : '已不在（可视为中断残留行，按「失败/中断」补记结论）'}。\\n${resume}`)\n  }\n  return result(true, `${head}\\n${checksLine}\\n无悬空派工（零「已派工」行）；锁文件 ${lockExists ? '存在（异常：无悬空行却有锁，请人工核对）' : '不在'}。\\n${resume}`)\n}\n\n/**\n * D5 · 旧台账迁移（v1 → v2 一次性转换）：补身份行 → 明细列补齐（缺列填「—」）→\n * 不可解析行原样保留并标注；写回前备份原文到 预算台账-v1备份-YYYYMMDD.md。\n * 历史任务目录迁移演练请在 `.tmp/` 副本上做（02 §二 禁止触碰项：不改他任务目录原件）。\n * @returns {{ok: boolean, message: string}}\n */\nexport function migrateLedger(rootDir, taskDirInput) {\n  const taskDir = resolveTaskDir(rootDir, taskDirInput)\n  if (taskDir === undefined) return result(false, '参数 taskDir 不能为空。')\n  const ledgerPath = join(taskDir, '预算台账.md')\n  if (!isFile(ledgerPath)) {\n    return result(false, `迁移失败：${ledgerPath} 不存在。`)\n  }\n  let text\n  try {\n    text = readFileSync(ledgerPath, 'utf8')\n  } catch (error) {\n    return result(false, `迁移失败：预算台账不可读（${ledgerPath}）：${renderThrown(error)}。`)\n  }\n  const up = upgradeLedgerText(text, rootDir, taskDir)\n  if (!up.upgraded) {\n    return result(true, `无需迁移：${ledgerPath} 已是 schema v2。`)\n  }\n  const backupPath = join(taskDir, `预算台账-v1备份-${todayCompact()}.md`)\n  try {\n    if (!existsSync(backupPath)) writeFileSync(backupPath, text, 'utf8')\n    writeFileSync(ledgerPath, up.text, 'utf8')\n  } catch (error) {\n    return result(false, `迁移写回失败（${ledgerPath}）：${renderThrown(error)}（v1 原文仍在）。`)\n  }\n  return result(true, `迁移完成：${relTaskPath(rootDir, taskDir)} 预算台账 v1 → v2（${up.note}）；v1 原文备份 = ${backupPath}。`)\n}\n\n/** Install the dispatch_begin / dispatch_end / dispatch_status / dispatch_migrate tools. */\nexport function apply(ctx) {\n  ctx.effect(() => {\n    const disposers = []\n    disposers.push(ctx.tools.register({\n      name: 'dispatch_begin',\n      description: '派工原子半步（前段）：读任务 状态.md 固定块 + 读 预算台账.md 固定块对照任务包预算块三项硬上限（**达上限即派工前拒绝**）→ 台账 schema v2 惰性升级（v1→v2 备份原文）→ 写 <taskDir>/.lock → 台账**预登记**一行（结论列=已派工，runId 列=完整 runId）→ 返回 runId。随后用 run_in_background:false 调 subagent_reviewer/subagent_developer，返回后调 dispatch_end 回填。同一任务目录已有锁时拒绝并发派工；账本身份行与任务目录不符时拒绝派工（防串档）。',\n      parameters: DISPATCH_BEGIN_PARAMETERS,\n      output: {\n        schema: DISPATCH_OUTPUT_SCHEMA,\n        render: (_args, value) => [{ type: 'text', text: value.message }],\n      },\n      async execute(args, exec) {\n        const root = sessionRoot(exec.agent)\n        return dispatchBegin(root, args?.taskDir, args?.环节, args?.角色, args?.模型)\n      },\n      presentCall: (args) => ({\n        card: 'generic',\n        title: '派工点火（预登记）',\n        kind: 'other',\n        ...(typeof args?.环节 === 'string' ? { rawInput: `${args.taskDir ?? ''} · ${args.环节} · ${args.角色 ?? ''}` } : {}),\n      }),\n    }))\n\n    disposers.push(ctx.tools.register({\n      name: 'dispatch_end',\n      description: '派工原子半步（后段）：核对 runId → **runId 精确结算**（台账按完整 runId 匹配「已派工」行；找不到=拒绝回填保留锁；行已有结论=重复结算拒绝；无「第一条已派工行」回退）→ 阶段前移合法性校验按**结果态六枚举**分支（DONE/DONE_WITH_CONCERNS 必须前移，DWC 另要求执行自测含「concerns」小节否则按证据缺失拒；NEEDS_CONTEXT/BLOCKED/FAILED/INTERRUPTED 不前移亦结算计次释锁）→ 台账回填该行结论（中文摘要照旧+〔状态词〕+结算后阶段/候选commit/token）→ 删锁。用于开发/验收阶段每次 B/C 派工返回后。',\n      parameters: DISPATCH_END_PARAMETERS,\n      output: {\n        schema: DISPATCH_OUTPUT_SCHEMA,\n        render: (_args, value) => [{ type: 'text', text: value.message }],\n      },\n      async execute(args, exec) {\n        const root = sessionRoot(exec.agent)\n        return dispatchEnd(root, args?.taskDir, args?.runId, args?.结论, args?.结果态, args?.token用量)\n      },\n      presentCall: (args) => ({\n        card: 'generic',\n        title: '派工回填（回填+解锁）',\n        kind: 'other',\n        ...(typeof args?.taskDir === 'string' ? { rawInput: args.taskDir } : {}),\n      }),\n    }))\n\n    disposers.push(ctx.tools.register({\n      name: 'dispatch_status',\n      description: '派工台账状态视图（恢复轮用）：列出预算台账明细行与累计、标出**悬空派工**（有「已派工」行且 .lock 仍在 = 已点火未回填）与锁文件状态；**四方一致检查**（账本身份行 vs 状态.md 头 vs 候选 commit vs 证据文件存在性）+ **续跑建议**（有通过结论行〔DONE/DONE_WITH_CONCERNS〕的环节不得重派，指向第一个无结论环节），供对账补记与悬空识别。',\n      parameters: {\n        type: 'object',\n        properties: {\n          taskDir: { type: 'string', description: '任务目录路径：相对项目根或绝对路径。' },\n        },\n        required: ['taskDir'],\n        additionalProperties: false,\n      },\n      output: {\n        schema: DISPATCH_OUTPUT_SCHEMA,\n        render: (_args, value) => [{ type: 'text', text: value.message }],\n      },\n      async execute(args, exec) {\n        const root = sessionRoot(exec.agent)\n        return dispatchStatus(root, args?.taskDir)\n      },\n      presentCall: (args) => ({\n        card: 'generic',\n        title: '查看派工台账',\n        kind: 'other',\n        ...(typeof args?.taskDir === 'string' ? { rawInput: args.taskDir } : {}),\n      }),\n    }))\n\n    disposers.push(ctx.tools.register({\n      name: 'dispatch_migrate',\n      description: '旧预算台账迁移（v1 → v2 一次性转换）：补账本身份行（taskId/schemaVersion/repoRelativeTaskPath/flowType）→ 明细列补齐（runId/attempt/派工前阶段/结算后阶段/candidateCommit/evidencePath 缺列填「—」）→ 不可解析行原样保留并标注；写回前备份原文到 预算台账-v1备份-YYYYMMDD.md。历史任务目录迁移演练在 .tmp/ 副本上做，不改原文件。',\n      parameters: {\n        type: 'object',\n        properties: {\n          taskDir: { type: 'string', description: '任务目录路径：相对项目根或绝对路径。' },\n        },\n        required: ['taskDir'],\n        additionalProperties: false,\n      },\n      output: {\n        schema: DISPATCH_OUTPUT_SCHEMA,\n        render: (_args, value) => [{ type: 'text', text: value.message }],\n      },\n      async execute(args, exec) {\n        const root = sessionRoot(exec.agent)\n        return migrateLedger(root, args?.taskDir)\n      },\n      presentCall: (args) => ({\n        card: 'generic',\n        title: '迁移预算台账 v1→v2',\n        kind: 'other',\n        ...(typeof args?.taskDir === 'string' ? { rawInput: args.taskDir } : {}),\n      }),\n    }))\n\n    return () => {\n      for (const dispose of disposers) dispose()\n    }\n  }, 'orchestrator2-dispatch lifecycle')\n}\n"
    },
    {
      "path": "plugins/dsh-orchestrator2/presets/orchestrator2/phase-gate.mjs",
      "content": "/**\n * Orchestrator2 phase gate: the machine half of the phase switch.\n *\n * Registers the `enter_auto_mode` model tool and performs the deterministic\n * create -> pause -> (idle) compactNow -> resume handoff:\n *\n *   enter_auto_mode(taskDir, objective?)\n *     1. validate <root>/<taskDir>/状态.md (parseable fixed header block,\n *        当前阶段 = 待审核), then branch on the header:\n *           - 状态头含 `设计目录` 字段 -> v2.x 路径: the pointer must point at\n *             a directory holding 任务包 01_需求分析.md + 02_开发方案与任务包.md;\n *             when 流程类型 = 产品设计全流程 the pointer's PARENT PARENT (the\n *             产品任务目录, i.e. 01-设计/<产品任务>/) must hold\n *             04_产品设计方案.md and 06_设计定稿记录.md whose fixed block\n *             parses 确认版本：vX.Y; finally the machine fuse 预算台账.md\n *             (固定块: 上限三项 + 当前累计行) must be present and parseable.\n *           - 状态头无 `设计目录` 字段 (v1.1 旧式状态头) -> legacy 仅开发路径:\n *             <taskDir>/开发计划/01_需求分析.md + 02_开发方案与任务包.md.\n *     1b. 开发准备门禁 (v2.1.4 · D2, fail-closed, 无流程类型豁免): the project-level\n *         record `<root>/00-项目管理/开发准备.md` must exist with a parseable\n *         fixed block carrying 规范版本 / 必要项 / 未通过项 / 最近复查 / 门禁结论,\n *         plus 必要项 >= 1, 未通过项 = 0 and 最近复查 as YYYY-MM-DD; the gate runs\n *         after the budget-ledger fuse and its rejection names the gap.\n *     2. single-package rule (both paths): any OTHER task dir under\n *        03-开发协同/ whose 状态.md parses to a phase that is neither\n *        待启动 nor 已完成 rejects the start.\n *     A missing or unparseable package returns an error text with NO side\n *     effects (no goal is created).\n *     3. ctx.goals.create(agent, { objective, maxGoalRounds: 24 }) - NOTE:\n *        this is a SERVICE-level call with no authority check, deliberately\n *        different from the model-facing `create_goal` tool (which requires a\n *        direct human turn). Single-user design: enter_auto_mode is itself\n *        triggered by the user's 「开始自动推进」 instruction, and the persona\n *        forbids calling it before user confirmation.\n *     4. ctx.goals.pause(agent, ref) immediately after create. While the goal\n *        is paused the goal-round-driver does not queue a round (it only\n *        drives armed active goals), so this turn ends and the agent goes\n *        idle with nothing scheduled - the race that would otherwise make\n *        \"compact before round 1\" nondeterministic cannot happen.\n *     5. store the PAUSED view (id + revision) keyed by agent id and return.\n *\n *   on agent/status === 'idle' with a stored intent:\n *     take-and-delete the intent, call ctx.compaction.compactNow(agent,\n *     signal), then - whether compactNow threw synchronously, rejected, or\n *     succeeded - call ctx.goals.resume(agent, ref) with the PAUSED view's\n *     revision (never the create view's: pause bumped it). A resume failure\n *     only logs; the user can say 「继续」 to rearm the goal manually.\n *\n * Exports follow the local-plugin shape of the 1.0 `phase-gate.mjs`\n * (`export const name`, `export const inject`, `export function apply(ctx)`).\n * `validateAutoMode` is an ADDITIONAL pure export used by the package's own\n * self-tests (mock single tests + e2e fixtures); the loader only reads the\n * plugin contract fields.\n *\n * This file deliberately imports ONLY node: builtins. Bare `@deepseek-ai/*`\n * specifiers do not resolve from a user preset directory (only row names in\n * agent.cordis.yml are rebased onto the harness), so the tool is registered\n * as a plain ToolDefinition object - the exact contract\n * `ctx.tools.register()` validates: { name, description, parameters (raw\n * JSON Schema), output: { schema, render }, execute }.\n */\n\nimport { createHash } from 'node:crypto'\nimport { readFileSync, statSync, readdirSync } from 'node:fs'\nimport { basename, dirname, isAbsolute, join, resolve } from 'node:path'\n\n/** Cordis plugin name used by loader diagnostics. */\nexport const name = 'orchestrator2-phase-gate'\n\n/** Hard dependencies: the compaction engine (group realm), the host goal service, the tool registry. */\nexport const inject = ['compaction', 'goals', 'tools']\n\n/** Round cap for the auto-advance goal (spec v2.0: 上限 24 工作轮；前景阻塞派工下每轮=一个真实工作步). */\nexport const MAX_GOAL_ROUNDS = 24\n\n/**\n * Fixed-header field the scheduler machine parses; values must be one of\n * these. 完整枚举 = 待启动 + 设计 9 态 + v2.1 场景扩展 3 态 + 开发 5 态主链 +\n * 修复循环 5 态 + 收尾中 + 已完成。\n *\n * v2.1 增量（+4，均为**追加**）：`现状研究中`（场景1 修改已有系统：需求沟通中\n * 之后，替代「同类产品搜索中 + 调研中」）、`方向确认中` / `清单待确认`（场景2\n * 技术调研储备：调研中 之前）、`待审查`（A2 验证并入代码审查后的合并环节名）。\n * 旧值全部保留可解析（`同类产品搜索中`/`调研中`/`验证` 位上的 `待验证`/\n * `待代码审查`/`待推送` 等）——旧项目状态头不报错；但 5 态语义对 7 态状态头会\n * 漂移，故规范 §十三 兼容性段要求 v2.0 项目先升级脚手架。\n * `待修订` 保留为回退态（计划审核驳回 / 需求变更），不列 5 态主链。\n */\nconst PHASE_VALUES = [\n  '待启动',\n  // 设计阶段（9 态）\n  '需求沟通中', '同类产品搜索中', '调研中', '方案设计中',\n  '待可行性复核', '原型制作中', '待设计确认', '方案已定稿', '任务包生成中',\n  // 设计阶段 · v2.1 场景扩展（3 态）\n  '现状研究中',\n  '方向确认中', '清单待确认',\n  // 开发阶段（v2.1 收敛为 5 态主链；待修订 = 回退态）\n  '待审核', '执行中', '待审查', '待构建', '待人工测试',\n  '待修订',\n  // 验收修复循环（5 态）\n  '修复包生成中', '修复中', '待修复审查', '待调度员检查', '待构建更新',\n  // 收尾 / 兼容（旧值保留）\n  '收尾中', '已完成', '待推送',\n  '待验证', '待代码审查',\n]\n\n/** Phases that count as \"not running\" for the single-package rule. */\nconst NOT_RUNNING_PHASES = new Set(['待启动', '已完成'])\n\n/**\n * 本机插件所实现的规范版本（M4：状态头 `规范版本` 字段的**唯一合法 v2.x 值**）。\n * 状态头显式声明该字段后，校验才不再依赖「有没有 设计目录 字段」这种结构推断。\n */\nexport const SUPPORTED_SPEC_VERSION = 'v2.1'\n\n/** 规范版本枚举：v1.1（旧项目，应改用 1.0 预设）/ v2.0（在途，需升级脚手架）/ v2.1（本预设）。 */\nconst SPEC_VERSIONS = ['v1.1', 'v2.0', 'v2.1']\n\n/** 流程类型枚举（缺省 仅开发）。 */\nconst FLOW_TYPES = ['产品设计全流程', '仅开发', '技术调研储备']\n\n/** 需要设计目录 + 04/06 全流程校验的流程类型。 */\nconst DESIGN_FLOW_TYPES = new Set(['产品设计全流程'])\n\n/** 预算台账文件名与「不要求台账」的流程类型。\n *  技术调研储备（场景2）= 独立终态调研流程，协同区无预算台账，故豁免台账校验。\n *  其余 v2.x 流程类型（产品设计全流程 / 仅开发）一律要求台账存在且固定块可解析\n *  —— 不按「状态头有没有引用台账」做条件豁免（那会让存量包静默跳过机器保险丝）。 */\nconst BUDGET_LEDGER_NAME = '预算台账.md'\nconst LEDGER_EXEMPT_FLOW_TYPES = new Set(['技术调研储备'])\n\n/** 台账固定块解析结果（M4/P2-2 fail-closed：缺席/不可解析都要能点出到底缺什么）。 */\nconst LEDGER_MISSING = { ok: false, reason: 'missing' }\nconst LEDGER_UNPARSABLE = { ok: false, reason: 'unparsable' }\nconst LEDGER_FORGIVEN = { ok: true, forgiven: true }\n\n/** 台账固定块上限三项的规范措辞（共用，避免多处文案漂移）。 */\nconst LEDGER_FIELDS_HINT = '（固定块需含「上限：C运行≤N / B运行≤N / 工作轮≤N」与「当前累计：C运行= / B运行= / 工作轮= / token用量=」两行）'\n\n/** 开发准备记录（项目级，D2 门禁唯一读取源；模板 = spec/templates/00-项目管理/开发准备.md）。 */\nconst PREP_RECORD_PATH = join('00-项目管理', '开发准备.md')\n\n/** 准备记录固定块五字段（与模板/persona/手册同口径的四方共享常量，禁止各处造词）。 */\nconst PREP_FIELDS = ['规范版本', '必要项', '未通过项', '最近复查', '门禁结论']\nconst PREP_FIELDS_HINT = `（固定块需含五行：${PREP_FIELDS.join(' / ')}）`\n\n/** 「最近复查」的日期形态（占位 — 不算日期；不收时间戳，口径最小可判）。 */\nconst PREP_DATE_RE = /^\\d{4}-\\d{2}-\\d{2}$/\n\n/** Render any thrown value the way the goal-round-driver does. */\nfunction renderThrown(value) {\n  return value instanceof Error ? value.message : String(value)\n}\n\n/** Whether one path exists and is a regular file. */\nfunction isFile(path) {\n  try {\n    return statSync(path).isFile()\n  } catch {\n    return false\n  }\n}\n\n/**\n * Parse a 状态.md / 06 定稿记录 / 预算台账 fixed header block (the only\n * machine-parsed source per the spec). Scans from the top of the file,\n * skips leading blank lines and `---` separators, collects `字段：值` lines,\n * and stops at the first blank line, `---` separator, a line without a `：`,\n * or a duplicate key.\n * @param {string} text - the whole document content.\n * @returns {Map<string, string>} the parsed header fields.\n */\nfunction parseFixedBlock(text) {\n  const fields = new Map()\n  const lines = String(text).split(/\\r\\n|\\r|\\n/)\n  let i = 0\n  while (i < lines.length && lines[i].trim() === '') i++\n  while (i < lines.length && lines[i].trim() === '---') i++\n  for (; i < lines.length; i++) {\n    const line = lines[i].trimEnd()\n    if (line.length === 0) break\n    if (line.trim() === '---') break\n    const separator = line.indexOf('：')\n    if (separator <= 0) break\n    const key = line.slice(0, separator).trim()\n    const value = line.slice(separator + 1).trim()\n    if (key.length === 0) break\n    if (fields.has(key)) break\n    fields.set(key, value)\n  }\n  return fields\n}\n\n/** Parse one file's fixed block. @returns {Map<string,string> | undefined} fields, or undefined when unreadable. */\nfunction parseFixedBlockFile(path) {\n  let text\n  try {\n    text = readFileSync(path, 'utf8')\n  } catch {\n    return undefined\n  }\n  return parseFixedBlock(text)\n}\n\n/** 文件内容的 SHA-256（小写十六进制）；不可读返回 undefined。M5 设计冻结核实用。 */\nfunction sha256OfFile(path) {\n  try {\n    return createHash('sha256').update(readFileSync(path)).digest('hex')\n  } catch {\n    return undefined\n  }\n}\n\n/**\n * Whether the 06 定稿记录 fixed block parses 确认版本：vX.Y.\n * @returns {string | undefined} the version string, or undefined.\n */\nfunction confirmVersionOf(designEntryPath) {\n  const fields = parseFixedBlockFile(designEntryPath)\n  if (fields === undefined) return undefined\n  const version = fields.get('确认版本')\n  if (typeof version !== 'string') return undefined\n  return /^v\\d+(\\.\\d+)+$/.test(version.trim()) ? version.trim() : undefined\n}\n\n/**\n * Whether the 预算台账 fixed block carries 上限三项 + 当前累计行 (the\n * machine fuse; v2.x 路径 + 引用台账的流程类型).\n * @returns {boolean} true when the block is present and parsable.\n */\nfunction budgetLedgerParsable(path) {\n  const fields = parseFixedBlockFile(path)\n  if (fields === undefined) return false\n  const cap = fields.get('上限')\n  const used = fields.get('当前累计')\n  if (typeof cap !== 'string' || typeof used !== 'string') return false\n  const capOk = /C运行≤\\d+/.test(cap) && /B运行≤\\d+/.test(cap) && /工作轮≤\\d+/.test(cap)\n  const usedOk = /C运行=\\d+/.test(used) && /B运行=\\d+/.test(used) && /工作轮=\\d+/.test(used) && /token用量=/.test(used)\n  return capOk && usedOk\n}\n\n/**\n * 预算台账机器保险丝（M4/P2-2 fail-closed）：v2.x + 非豁免流程类型**必须**有台账。\n * 技术调研储备（场景2）无台账 → 放行（不核对）。\n * @returns {{ok: true, forgiven?: true} | {ok: false, reason: 'missing' | 'unparsable', path?: string}}\n */\nfunction checkBudgetLedger({ taskDir, flowType }) {\n  if (LEDGER_EXEMPT_FLOW_TYPES.has(flowType)) return LEDGER_FORGIVEN\n  const ledger = join(taskDir, BUDGET_LEDGER_NAME)\n  if (!isFile(ledger)) return { ok: false, reason: 'missing', path: ledger }\n  if (!budgetLedgerParsable(ledger)) return { ok: false, reason: 'unparsable', path: ledger }\n  return { ok: true }\n}\n\n/**\n * 开发准备门禁（D2 fail-closed）：文件存在 ∧ 固定块可解析 ∧ 五字段齐备 ∧\n * `必要项` ≥1 ∧ `未通过项` = 0 ∧ `最近复查` 为日期形态 → 放行；任一不满足 →\n * 拒绝并在信息中点出缺口。纯文件检查、无新依赖、无流程类型豁免\n * （技术调研储备不进 enter_auto_mode；修复包不重新点火）。\n * `门禁结论` 字段由人填写留痕，**机器不消费其值**（判定只看上面五项）。\n * @param {string} rootDir - project root (absolute).\n * @returns {{ok: true} | {ok: false, message: string}}\n */\nfunction checkDevPrep(rootDir) {\n  const path = join(rootDir, PREP_RECORD_PATH)\n  if (!isFile(path)) {\n    return {\n      ok: false,\n      message: `开发准备门禁：缺少 ${path}。请先完成开发准备（新会话首条消息的引导，或按 spec/templates/00-项目管理/开发准备.md 模板建立记录）。`,\n    }\n  }\n  const fields = parseFixedBlockFile(path)\n  if (fields === undefined) {\n    return { ok: false, message: `开发准备门禁：固定块不可解析（${path}）${PREP_FIELDS_HINT}。` }\n  }\n  const missing = PREP_FIELDS.filter((key) => !fields.has(key))\n  if (missing.length > 0) {\n    return { ok: false, message: `开发准备门禁：固定块缺少字段 ${missing.join(' / ')}（${path}）${PREP_FIELDS_HINT}。` }\n  }\n  const required = Number(fields.get('必要项'))\n  if (!Number.isInteger(required) || required < 1) {\n    return {\n      ok: false,\n      message: `开发准备门禁：「必要项」须为 ≥1 的整数（${path} 当前=\"${fields.get('必要项')}\"）——请先在记录中登记本次开发的实际必要项。`,\n    }\n  }\n  const failed = Number(fields.get('未通过项'))\n  if (!Number.isInteger(failed) || failed < 0) {\n    return { ok: false, message: `开发准备门禁：「未通过项」须为 ≥0 的整数（${path} 当前=\"${fields.get('未通过项')}\"）。` }\n  }\n  if (failed > 0) {\n    return {\n      ok: false,\n      message: `开发准备门禁：未通过项=${failed}，逐项见 ${path}（补齐并复查后重新启动自动推进）。`,\n    }\n  }\n  if (!PREP_DATE_RE.test(fields.get('最近复查'))) {\n    return {\n      ok: false,\n      message: `开发准备门禁：「最近复查」须为日期形态 YYYY-MM-DD（${path} 当前=\"${fields.get('最近复查')}\"）——请复查必要项后更新该字段。`,\n    }\n  }\n  return { ok: true }\n}\n\n/** Case-insensitive path equality on Windows, exact elsewhere. */\nfunction samePath(a, b) {\n  const left = resolve(a)\n  const right = resolve(b)\n  return process.platform === 'win32'\n    ? left.toLowerCase() === right.toLowerCase()\n    : left === right\n}\n\n/**\n * Other task dirs under 03-开发协同/ whose 状态.md parses to a phase that is\n * NOT 待启动 / 已完成 (single-package serialisation rule; excludes the target\n * task dir itself).\n * @returns {Array<{name: string, phase: string}>}\n */\nfunction runningTasks(rootDir, taskDir) {\n  // ponytail: 每次调用全量扫描 03-开发协同；包数到几十个再考虑按修改时间缓存（单用户包规模小）。\n  const coordDir = join(rootDir, '03-开发协同')\n  let entries\n  try {\n    entries = readdirSync(coordDir, { withFileTypes: true })\n  } catch {\n    return []\n  }\n  const running = []\n  for (const entry of entries) {\n    if (!entry.isDirectory()) continue\n    const dir = join(coordDir, entry.name)\n    if (samePath(dir, taskDir)) continue\n    const statusPath = join(dir, '状态.md')\n    if (!isFile(statusPath)) continue\n    const header = parseFixedBlockFile(statusPath)\n    if (header === undefined) continue\n    const phase = header.get('当前阶段')\n    if (phase === undefined) continue\n    if (!NOT_RUNNING_PHASES.has(phase)) running.push({ name: entry.name, phase })\n  }\n  return running\n}\n\n/**\n * The model-visible JSON Schema (raw JSON Schema subset enforced by\n * dsh-tools) for the enter_auto_mode parameters.\n */\nconst ENTER_PARAMETERS = {\n  type: 'object',\n  properties: {\n    taskDir: {\n      type: 'string',\n      description: '任务目录路径：相对项目根（如 03-开发协同/TP1-<名>）或绝对路径。',\n    },\n    objective: {\n      type: 'string',\n      description: '推进目标描述；缺省为「推进 <任务目录名> 到『待人工测试』」。',\n    },\n  },\n  required: ['taskDir'],\n}\n\n/** Canonical output contract: { ok, message, goalId? }. */\nconst ENTER_OUTPUT_SCHEMA = {\n  type: 'object',\n  properties: {\n    ok: { type: 'boolean', description: '是否成功建立推进目标并挂起压缩意图。' },\n    message: { type: 'string', description: '给调度器（模型）的结果文本。' },\n    goalId: { type: 'string', description: '已建立 goal 的 id（成功时）。' },\n  },\n  required: ['ok', 'message'],\n  additionalProperties: false,\n}\n\n/**\n * Build the tool result value.\n * @param {boolean} ok - success flag.\n * @param {string} message - model-facing text.\n * @param {string} [goalId] - created goal id, success only.\n */\nfunction result(ok, message, goalId) {\n  return { ok, message, ...(goalId === undefined ? {} : { goalId }) }\n}\n\n/**\n * Resolve the project root for one agent: the session's selected workspace,\n * falling back to the process working directory.\n */\nfunction sessionRoot(agent) {\n  const cwd = agent?.session?.header?.cwd\n  if (typeof cwd === 'string' && cwd.length > 0) return cwd\n  return process.cwd()\n}\n\n/**\n * Validate the start conditions: 状态头 fail-closed 解析（M4）→ 规范版本分支 ×\n * 流程类型分支二维判定 → 预算台账机器保险丝（M4/P2-2）→ 设计目录 / 产品设计全流程\n * 校验（M4/M5）→ 幂等（M3）→ 单包串行。纯文件检查；NO side effects.\n *\n * 分支总览（M4 §2 的二维矩阵）：\n *   - 缺 `规范版本` 字段 / 未知值 / v1.1 → 拒绝（v1.1 应改用 1.0 预设，同项目不混用）；\n *   - v2.x + 设计目录缺失 → 拒绝（v2.1 起「设计目录」为 v2.x 必填；legacy 结构由 v1.1 分支覆盖）；\n *   - v2.x + 流程类型=产品设计全流程 → 需 04/06 + 确认版本（M5 另核设计基线哈希）；\n *   - v2.x + 引用预算台账 → 台账必须存在且固定块可解析；\n *   - 未知流程类型 → 拒绝。\n * @param {string} rootDir - project root (absolute).\n * @param {string} taskDirInput - task dir path, relative or absolute.\n * @param {Record<string, unknown>} [products] - 机器产品接口（M2/M3/M5）：\n *   `{ goalLookup?: (taskDirPath: string) => ({id: string, state?: string} | undefined) }`\n *   ——宿主/适配层注入，缺省无幂等检查（纯文件校验保持可单测）；\n *   `designFreeze` 由本模块自行从状态头/任务包推导，不需要注入。\n * @returns {{ok: true} | {ok: false, message: string}}\n */\nexport function validateAutoMode(rootDir, taskDirInput, products = {}) {\n  const input = typeof taskDirInput === 'string' ? taskDirInput.trim() : ''\n  if (input.length === 0) {\n    return { ok: false, message: '参数 taskDir 不能为空：请传入任务目录路径（如 03-开发协同/<任务目录>）。' }\n  }\n  const taskDir = isAbsolute(input) ? input : join(rootDir, input)\n  const statusPath = join(taskDir, '状态.md')\n  if (!isFile(statusPath)) {\n    return { ok: false, message: `任务状态不存在：缺少 ${statusPath}（请确认任务目录路径与协同区同名目录）。` }\n  }\n  const header = parseFixedBlockFile(statusPath)\n  if (header === undefined) {\n    return { ok: false, message: `状态.md 顶部固定格式块不可解析（${statusPath}）。` }\n  }\n  const phase = header.get('当前阶段')\n  if (phase === undefined) {\n    return { ok: false, message: `状态.md 顶部固定格式块不可解析：未找到「当前阶段」字段（${statusPath}）。` }\n  }\n  if (!PHASE_VALUES.includes(phase)) {\n    return { ok: false, message: `状态.md 顶部固定格式块不可解析：「当前阶段」值 \"${phase}\" 不在阶段枚举内（${statusPath}）。` }\n  }\n\n  // ── M4 · 显式规范版本（缺失即拒绝，不再由「有无设计目录」推断版本）────────\n  const specVersion = header.get('规范版本')\n  if (specVersion === undefined) {\n    return {\n      ok: false,\n      message: `状态.md 顶部固定格式块缺少必填字段「规范版本」（${statusPath}）。请补写一行 \\`规范版本：${SUPPORTED_SPEC_VERSION}\\`（升级脚手架引导：存量任务原地补写该字段，其余不动）。`,\n    }\n  }\n  if (!SPEC_VERSIONS.includes(specVersion)) {\n    return {\n      ok: false,\n      message: `「规范版本」值 \"${specVersion}\" 不在版本枚举内（${statusPath}）。合法值：${SPEC_VERSIONS.join(' / ')}。`,\n    }\n  }\n  if (specVersion === 'v1.1') {\n    return {\n      ok: false,\n      message: `规范版本 ${specVersion} 的项目请改用 1.0 预设「自动开发调度器」——同一项目不混用两个预设（状态机与校验逻辑不同，混用会错乱）。`,\n    }\n  }\n\n  // ── M4 · 流程类型枚举（未知值 fail-closed）────────────────────────────────\n  const flowType = header.get('流程类型') || '仅开发'\n  if (!FLOW_TYPES.includes(flowType)) {\n    return {\n      ok: false,\n      message: `「流程类型」值 \"${flowType}\" 不在枚举内（${statusPath}）。合法值：${FLOW_TYPES.join(' / ')}（缺省 仅开发）。`,\n    }\n  }\n\n  // ── M4 · 设计目录指针（v2.x 必填；legacy 结构已由 v1.1 分支拦下）──────────\n  const designDir = header.get('设计目录')\n  if (designDir === undefined) {\n    return {\n      ok: false,\n      message: `流程类型=${flowType} 的 v2.x 任务包缺少「设计目录」指针（${statusPath}）。请补写 \\`设计目录：01-设计/<产品任务>/任务包/<TP编号>-<名>\\`（场景2 技术调研储备写 \\`01-设计/技术调研/<主题>\\`）。`,\n    }\n  }\n\n  // ── M4/P2-2 · 预算台账机器保险丝 ─────────────────────────────────────────\n  const ledger = checkBudgetLedger({ taskDir, flowType })\n  if (!ledger.ok && ledger.reason === 'missing') {\n    return {\n      ok: false,\n      message: `机器保险丝：缺少 ${BUDGET_LEDGER_NAME}（${ledger.path}）。请在协同区任务目录建立预算台账${LEDGER_FIELDS_HINT}（流程类型=${flowType}；仅「技术调研储备」豁免台账）。`,\n    }\n  }\n  if (!ledger.ok) {\n    return {\n      ok: false,\n      message: `${BUDGET_LEDGER_NAME} 固定块不可解析${LEDGER_FIELDS_HINT}（${ledger.path}）。`,\n    }\n  }\n\n  // ── D2 · 开发准备门禁（fail-closed；项目级记录，无流程类型豁免）────────────\n  const prep = checkDevPrep(rootDir)\n  if (!prep.ok) return { ok: false, message: prep.message }\n\n  // ── 设计目录内容 + 产品设计全流程 04/06（含 M5 设计冻结哈希核对）──────────\n  const invalid = validateV2Path(rootDir, taskDir, designDir, header, flowType, products)\n  if (invalid !== undefined) return invalid\n\n  // ── M3 · 幂等防护：同一任务目录不得有第二个推进 goal ──────────────────────\n  const goalLookup = products?.goalLookup\n  if (typeof goalLookup === 'function') {\n    let existing\n    try {\n      existing = goalLookup(taskDir)\n    } catch (error) {\n      return { ok: false, message: `幂等守卫查询失败：${renderThrown(error)}（保守拒绝，避免重复建立推进目标）。` }\n    }\n    if (existing !== undefined && existing !== null) {\n      const state = typeof existing.state === 'string' && existing.state.length > 0 ? `，状态=${existing.state}` : ''\n      return {\n        ok: false,\n        message: `幂等拒绝：任务目录已存在推进 goal（goal ${String(existing.id)}${state}）。enter_auto_mode 对同一任务目录只启动一次——已 active/paused 的 goal 请用「继续」恢复，确需重来先 update_goal(complete/blocked) 关掉旧目标。`,\n      }\n    }\n  }\n\n  // ── M4 · 规范版本 × 流程类型的阶段闸门（只对 v2.1 放行待审核）────────────\n  if (specVersion === SUPPORTED_SPEC_VERSION && phase !== '待审核') {\n    return { ok: false, message: `当前阶段为「${phase}」而非「待审核」：enter_auto_mode 只在任务包激活（等待第一次授权）时启动自动推进。` }\n  }\n  if (specVersion !== SUPPORTED_SPEC_VERSION && phase !== '待审核') {\n    return {\n      ok: false,\n      message: `规范版本 ${specVersion} 在途任务包（当前阶段「${phase}」）：请按旧流水线走完本包——${SUPPORTED_SPEC_VERSION} 的 5 态语义对旧状态头会漂移，本预设只对 ${SUPPORTED_SPEC_VERSION} 任务包的「待审核」放行。`,\n    }\n  }\n\n  const running = runningTasks(rootDir, taskDir)\n  if (running.length > 0) {\n    return {\n      ok: false,\n      message: `单包串行铁则：以下任务尚未完成（既非「待启动」亦非「已完成」），请先完成在跑任务再启动本包：${running.map((r) => `${r.name}（${r.phase}）`).join('、')}。`,\n    }\n  }\n  return { ok: true }\n}\n\n/**\n * v2.x 路径校验：设计目录指针指向的任务包 01/02；（流程类型=产品设计全流程时）\n * 设计目录的上级产品任务目录下的 04/06 + 确认版本 + 设计冻结哈希核对（M5）。\n * 内容与「预算台账」已在 validateAutoMode 中前置校验（顺序由 M4 二维分支决定）。\n * @returns {{ok: false, message: string} | undefined} an error result, or undefined when valid.\n */\nfunction validateV2Path(rootDir, taskDir, designDir, header, flowType, products) {\n  const designTaskDirAbs = isAbsolute(designDir) ? designDir : join(rootDir, designDir)\n  for (const label of ['01_需求分析.md', '02_开发方案与任务包.md']) {\n    const path = join(designTaskDirAbs, label)\n    if (!isFile(path)) {\n      return { ok: false, message: `设计目录校验失败：缺少 ${label}（${path}）。状态头「设计目录」指针应指向 01-设计/<产品任务>/任务包/<TP编号>-<名>/。` }\n    }\n  }\n  if (DESIGN_FLOW_TYPES.has(flowType)) {\n    // 04/06 在 设计目录 的上级产品任务目录（= 设计目录/../..，即 01-设计/<产品任务>/），\n    // 不是设计任务包目录内——防错误层级固化（误放设计目录内应拒）。\n    // ponytail: 固定两级上溯（设计目录=…/任务包/<TP>，规范固化布局）；布局可自定义时再引入配置。\n    const productDir = join(designTaskDirAbs, '..', '..')\n    if (!isFile(join(productDir, '04_产品设计方案.md'))) {\n      return { ok: false, message: `流程类型=产品设计全流程：缺少 04_产品设计方案.md（${join(productDir, '04_产品设计方案.md')}）。04/06 应放在设计目录的上级产品任务目录（01-设计/<产品任务>/），不是任务包目录内。` }\n    }\n    const designEntry = join(productDir, '06_设计定稿记录.md')\n    if (!isFile(designEntry)) {\n      return { ok: false, message: `流程类型=产品设计全流程：缺少 06_设计定稿记录.md（${designEntry}）。` }\n    }\n    const version = confirmVersionOf(designEntry)\n    if (version === undefined) {\n      return { ok: false, message: `06_设计定稿记录.md 顶部固定块缺少可解析的「确认版本：vX.Y」字段（${designEntry}）。` }\n    }\n    const freeze = verifyDesignFreeze({ taskDir, productDir, header, products })\n    if (freeze !== undefined) return freeze\n  }\n  return undefined\n}\n\n/**\n * M5 · 设计冻结哈希核对。\n * 口径（计划审核注意事项④）：**任务包 02 引用基线 ID 才核对哈希**（未引用不核，\n * 历史包不强制）；基线文件位于产品任务目录 `设计基线.json`（模板\n * `spec/01-设计/_模板/设计基线.example.json` / `01-设计/_模板/设计基线.example.json`\n * （v2.1.5 起模板收进 `_模板/`；原 `spec/03-开发协同/…` 历史位写法一并按新树口径顺改）。\n * @returns {{ok: false, message: string} | undefined} an error result, or undefined when ok/skipped.\n */\nfunction verifyDesignFreeze({ taskDir, productDir, header, products }) {\n  void products\n  const referenced = [...header.values()].some((v) => v.includes('设计基线'))\n  const baselinePath = join(productDir, '设计基线.json')\n  const baselineReferenced = referenced || isFile(baselinePath)\n  if (!baselineReferenced) return undefined\n  if (!isFile(baselinePath)) {\n    return {\n      ok: false,\n      message: `设计冻结校验失败：状态头/任务包引用了设计基线但找不到 ${baselinePath}（基线 ID 未知）。请在关卡1 用调度员动作生成「设计基线.json」（基线 ID + 确认版本 + 确认时间 + 04/05/原型/06 的 SHA-256 映射）。`,\n    }\n  }\n  let baseline\n  try {\n    baseline = JSON.parse(readFileSync(baselinePath, 'utf8'))\n  } catch (error) {\n    return { ok: false, message: `设计基线.json 不是合法 JSON（${baselinePath}）：${renderThrown(error)}。` }\n  }\n  const baselineId = String(baseline?.baselineId ?? baseline?.['基线ID'] ?? '?')\n  const confirmedVersion = String(baseline?.confirmedVersion ?? baseline?.['确认版本'] ?? '?')\n  const files = baseline?.files\n  if (files === null || typeof files !== 'object') {\n    return { ok: false, message: `设计基线.json（ID ${baselineId}，确认版本 ${confirmedVersion}）缺少 files 清单（${baselinePath}）：需为 { 相对路径: SHA-256 } 映射。` }\n  }\n  const mismatched = []\n  const absent = []\n  for (const [rel, expected] of Object.entries(files)) {\n    const target = isAbsolute(rel) ? rel : join(productDir, ...String(rel).split('/'))\n    if (!isFile(target)) {\n      absent.push(rel)\n      continue\n    }\n    const actual = sha256OfFile(target)\n    if (typeof expected !== 'string' || actual !== expected.toLowerCase()) {\n      mismatched.push(`${rel}（基线 ${String(expected).slice(0, 12)}… / 当前 ${String(actual).slice(0, 12)}…）`)\n    }\n  }\n  if (absent.length > 0 || mismatched.length > 0) {\n    const parts = []\n    if (absent.length > 0) parts.push(`文件缺失：${absent.join('、')}`)\n    if (mismatched.length > 0) parts.push(`哈希不符：${mismatched.join('、')}`)\n    return {\n      ok: false,\n      message: `设计冻结校验失败：设计基线（ID ${baselineId}，确认版本 ${confirmedVersion}）与当前设计件不符——${parts.join('；')}。设计件在确认后被改动，请重新走关卡1 或回退重生成基线（ID 递增），再启动自动推进。`,\n    }\n  }\n  return undefined\n}\n\n/** Install the enter_auto_mode tool and the idle-compaction handoff. */\nexport function apply(ctx) {\n  /** Paused-goal intents waiting for the agent's next idle transition, keyed by agent id. */\n  const pendingByAgent = new Map()\n  /** Abort controllers of in-flight handoffs, so plugin unload can cancel them. */\n  const activeControllers = new Set()\n\n  /** One deterministic handoff: compact now, then resume no matter what. */\n  async function runHandoff(agent, ref) {\n    const controller = new AbortController()\n    activeControllers.add(controller)\n    try {\n      await ctx.compaction.compactNow(agent, controller.signal)\n    } catch (error) {\n      // Compaction is an optimization, not a gate: any failure (busy,\n      // cancelled, summary, commit, ...) degrades to the pressure-driven\n      // automatic compaction and the goal still resumes.\n      ctx.logger.warn(`orchestrator2-phase-gate: compaction before the first round failed for agent \"${agent.id}\": ${renderThrown(error)}`)\n    } finally {\n      activeControllers.delete(controller)\n      try {\n        // Resume with the PAUSED view's revision - pause bumped it past the\n        // create revision, and goals.resume rejects stale refs.\n        ctx.goals.resume(agent, { id: ref.id, revision: ref.revision })\n      } catch (error) {\n        ctx.logger.warn(`orchestrator2-phase-gate: could not resume goal \"${ref.id}\" (revision ${ref.revision}) for agent \"${agent.id}\": ${renderThrown(error)}；用户可说「继续」手动 resume`)\n      }\n    }\n  }\n\n  ctx.on('agent/status', ({ agent, status }) => {\n    if (status !== 'idle') return\n    const ref = pendingByAgent.get(agent.id)\n    if (ref === undefined) return\n    pendingByAgent.delete(agent.id)\n    void runHandoff(agent, ref)\n  })\n\n  ctx.effect(() => {\n    const disposeTool = ctx.tools.register({\n      name: 'enter_auto_mode',\n      description: '进入自动推进模式（阶段二）。前置条件：任务包已齐备且用户已明确确认并说「开始自动推进」。校验任务目录的 状态.md（顶部固定格式块可解析、当前阶段=待审核；按「设计目录」字段分支 v2.x 路径——设计目录下 01、02、上级产品任务目录 04/06+确认版本、预算台账机器保险丝——或 legacy 仅开发路径）+ 开发准备门禁（00-项目管理/开发准备.md 固定块 fail-closed：必要项≥1、未通过项=0、最近复查为日期）+ 单包串行校验（排除在跑任务），然后建立推进 goal（推进到『待人工测试』，上限 24 轮）并挂起：本会话本轮结束转 idle 后先压缩上下文，再自动开始第一轮推进。不得在用户未确认时调用。',\n      parameters: ENTER_PARAMETERS,\n      output: {\n        schema: ENTER_OUTPUT_SCHEMA,\n        render: (_args, value) => [{ type: 'text', text: value.message }],\n      },\n      async execute(args, exec) {\n        const agent = exec.agent\n        if (agent === undefined) {\n          return result(false, 'enter_auto_mode 需要一个调用方 agent（当前工具调用无 agent 上下文）。')\n        }\n        const invalid = validateAutoMode(sessionRoot(agent), typeof args?.taskDir === 'string' ? args.taskDir : '')\n        if (!invalid.ok) return result(false, invalid.message)\n        const taskDirInput = typeof args?.taskDir === 'string' ? args.taskDir.trim() : ''\n        const taskDir = isAbsolute(taskDirInput) ? taskDirInput : join(sessionRoot(agent), taskDirInput)\n        const taskDirName = basename(taskDir.replace(/[\\\\/]+$/, ''))\n        const objective = typeof args?.objective === 'string' && args.objective.trim().length > 0\n          ? args.objective.trim()\n          : `推进 ${taskDirName} 到『待人工测试』`\n        // Service-level goal creation: no authority check by design (see the\n        // module header) - the model-facing create_goal tool is the\n        // human-gated layer; this call is the scheduler's own machine path.\n        let created\n        try {\n          created = ctx.goals.create(agent, { objective, maxGoalRounds: MAX_GOAL_ROUNDS })\n        } catch (error) {\n          return result(false, `建立推进目标失败：${renderThrown(error)}`)\n        }\n        let paused\n        try {\n          paused = ctx.goals.pause(agent, { id: created.id, revision: created.revision })\n        } catch (error) {\n          return result(false, `推进目标已建立（goal ${created.id}）但挂起失败：${renderThrown(error)}；goal 处于活动状态，自动推进将在未做首压缩的情况下开始（压缩退化为压力自动压缩）。`)\n        }\n        pendingByAgent.set(agent.id, { id: paused.id, revision: paused.revision })\n        return result(\n          true,\n          `已建立推进目标（goal ${paused.id}，上限 ${MAX_GOAL_ROUNDS} 轮）并挂起压缩：本轮结束后会话转 idle 时将先压缩上下文，然后自动开始第一轮推进。`,\n          paused.id,\n        )\n      },\n      presentCall: (args) => ({\n        card: 'generic',\n        title: '进入自动推进模式',\n        kind: 'other',\n        ...(typeof args?.taskDir === 'string' ? { rawInput: args.taskDir } : {}),\n      }),\n    })\n    return () => {\n      disposeTool()\n      pendingByAgent.clear()\n      for (const controller of activeControllers) controller.abort()\n      activeControllers.clear()\n    }\n  }, 'orchestrator2-phase-gate lifecycle')\n}\n"
